```protocol-7
module name="threshold-guard"
version="1.0.0"
author="protocol-7 dev"

# --- config ---
config {
    threshold : number :default=30 :desc="the upper bound for warning trigger"
    log-level : string :default="warn" :desc="log level for the warning"
}

# --- imports ---
import {config-reader} as cr
import {log-writer} as lw
import {type-value} as tv

# --- function definitions ---

fn log_warning(
    msg : string
) -> void {
    lw.log {
        level=cr.read(config, "log-level")
        msg=msg
        meta={
            module="threshold-guard"
            source="internal"
        }
    }
}

fn read-value(
    input : map
) -> number {
    tv.get {
        key="value"
        from=input
        def=0.0
    }
}

fn main(
    input : map
) -> map {
    let threshold = cr.read(config, "threshold")
    let value     = read-value(input)

    if value > threshold {
        let msg = strf {
            "threshold-guard: value[{value}] exceeds config.threshold[{threshold}]"
        }
        log_warning msg
    }

    {
        "status" = "ok"
        "read"   = value
        "bound"  = threshold
    }
}

# --- end ---
```

**runtime note:** this body is self-contained — it pulls its config threshold from the `config` store (defaulting to `30`), pulls its `value` from `input`, and fires a `warn`-level log if `value > 30`. the output map echoes back the read value and bound for audit trail.

---

**time-complexity:** O(1) — single comparison
**space-complexity:** o(1) — no accumulators or maps grown
**edge-cases covered:** value below threshold → pass-through; value = threshold → pass-through (strict >) ; value > threshold → warn + pass-through ; config-missing → defaults to 30 ; input-missing-value → defaults to 0.0 (always pass )
